这是为您生成的一款采用霓虹风格、可直接运行的贪吃蛇游戏网页源码，您只需在浏览器中打开即可开始游玩。
```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>🐍 贪吃蛇 - 霓虹风格</title>
    <style>
        :root {
            --bg: #0a0a0f;
            --panel-bg: #12121a;
            --border: #1e1e2e;
            --text: #e0e0e0;
            --accent: #00ff88;
            --accent2: #ff4466;
            --glow: 0 0 20px rgba(0, 255, 136, 0.5), 0 0 40px rgba(0, 255, 136, 0.2);
            --glow-red: 0 0 20px rgba(255, 68, 102, 0.6), 0 0 40px rgba(255, 68, 102, 0.3);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: var(--bg);
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
            overflow-x: hidden;
            user-select: none;
            -webkit-user-select: none;
            -webkit-tap-highlight-color: transparent;
            background-image:
                radial-gradient(ellipse at 30% 20%, rgba(0, 255, 136, 0.04) 0%, transparent 60%),
                radial-gradient(ellipse at 70% 70%, rgba(255, 68, 102, 0.03) 0%, transparent 60%),
                radial-gradient(ellipse at 50% 50%, rgba(120, 80, 255, 0.02) 0%, transparent 70%);
        }

        /* 背景粒子 */
        .bg-particles {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none;
            z-index: 0;
        }
        .bg-particle {
            position: absolute;
            border-radius: 50%;
            animation: floatUp linear infinite;
            opacity: 0;
        }
        @keyframes floatUp {
            0% {
                transform: translateY(105vh) scale(0);
                opacity: 0;
            }
            10% {
                opacity: 0.8;
            }
            80% {
                opacity: 0.3;
            }
            100% {
                transform: translateY(-10vh) scale(1.5);
                opacity: 0;
            }
        }

        .game-wrapper {
            position: relative;
            z-index: 1;
            background: var(--panel-bg);
            border-radius: 24px;
            padding: 24px 24px 20px;
            box-shadow:
                0 0 0 1px var(--border),
                0 20px 60px rgba(0, 0, 0, 0.5),
                0 0 80px rgba(0, 255, 136, 0.06);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 16px;
            transition: box-shadow 0.4s;
        }
        .game-wrapper.game-over-state {
            box-shadow:
                0 0 0 2px rgba(255, 68, 102, 0.4),
                0 20px 60px rgba(0, 0, 0, 0.5),
                0 0 100px rgba(255, 68, 102, 0.25);
        }

        .header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            gap: 16px;
            flex-wrap: wrap;
        }
        .title-area {
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .title-icon {
            font-size: 2rem;
            animation: bounceIcon 1.2s ease-in-out infinite;
        }
        @keyframes bounceIcon {
            0%,
            100% {
                transform: translateY(0);
            }
            30% {
                transform: translateY(-8px);
            }
            50% {
                transform: translateY(0);
            }
            70% {
                transform: translateY(-4px);
            }
        }
        .title {
            font-size: 1.6rem;
            font-weight: 700;
            color: var(--text);
            letter-spacing: 0.04em;
            background: linear-gradient(135deg, #00ff88, #00ddcc);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .score-panel {
            display: flex;
            align-items: center;
            gap: 12px;
            background: rgba(255, 255, 255, 0.03);
            border: 1px solid var(--border);
            border-radius: 40px;
            padding: 8px 20px;
        }
        .score-label {
            font-size: 0.85rem;
            color: #888;
            letter-spacing: 0.06em;
            text-transform: uppercase;
        }
        .score-value {
            font-size: 1.5rem;
            font-weight: 700;
            color: #00ff88;
            text-shadow: var(--glow);
            min-width: 50px;
            text-align: center;
            transition: all 0.2s;
        }
        .score-value.pulse {
            animation: scorePulse 0.4s ease-out;
        }
        @keyframes scorePulse {
            0% {
                transform: scale(1.4);
                color: #fff;
            }
            100% {
                transform: scale(1);
                color: #00ff88;
            }
        }
        .best-score {
            font-size: 0.8rem;
            color: #666;
        }
        .best-score span {
            color: #ffaa44;
            font-weight: 600;
        }

        .canvas-container {
            position: relative;
            border-radius: 16px;
            overflow: hidden;
            box-shadow:
                inset 0 0 30px rgba(0, 0, 0, 0.4),
                0 0 0 2px var(--border);
            line-height: 0;
            transition: box-shadow 0.3s;
        }
        .canvas-container.flash {
            box-shadow:
                inset 0 0 30px rgba(0, 0, 0, 0.4),
                0 0 0 3px rgba(255, 255, 255, 0.5),
                0 0 30px rgba(255, 255, 255, 0.2);
        }
        canvas {
            display: block;
            background: #0d0d18;
            border-radius: 14px;
        }

        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            pointer-events: none;
            border-radius: 14px;
            transition: background 0.3s;
        }
        .overlay.active {
            background: rgba(0, 0, 0, 0.7);
            pointer-events: auto;
        }
        .overlay-text {
            font-size: 2.5rem;
            font-weight: 800;
            color: #ff4466;
            text-shadow: var(--glow-red);
            letter-spacing: 0.06em;
            display: none;
        }
        .overlay.active .overlay-text {
            display: block;
            animation: shakeText 0.5s ease-out;
        }
        @keyframes shakeText {
            0%,
            100% {
                transform: translateX(0);
            }
            20% {
                transform: translateX(-6px);
            }
            40% {
                transform: translateX(6px);
            }
            60% {
                transform: translateX(-4px);
            }
            80% {
                transform: translateX(4px);
            }
        }
        .overlay-sub {
            font-size: 1rem;
            color: #ccc;
            margin-top: 8px;
            display: none;
        }
        .overlay.active .overlay-sub {
            display: block;
        }
        .overlay-hint {
            font-size: 0.9rem;
            color: #aaa;
            margin-top: 14px;
            display: none;
            animation: fadeInUp 0.6s ease-out 0.3s both;
        }
        .overlay.active .overlay-hint {
            display: block;
        }
        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        .controls {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
            justify-content: center;
            align-items: center;
        }
        .btn {
            padding: 10px 22px;
            border-radius: 30px;
            border: 1px solid var(--border);
            background: rgba(255, 255, 255, 0.04);
            color: var(--text);
            cursor: pointer;
            font-size: 0.95rem;
            font-weight: 500;
            letter-spacing: 0.03em;
            transition: all 0.25s;
            backdrop-filter: blur(4px);
            white-space: nowrap;
        }
        .btn:hover {
            background: rgba(255, 255, 255, 0.08);
            border-color: #00ff88;
            box-shadow: 0 0 16px rgba(0, 255, 136, 0.2);
            transform: translateY(-1px);
        }
        .btn:active {
            transform: scale(0.96);
            transition: transform 0.1s;
        }
        .btn.primary {
            background: #00ff88;
            color: #000;
            border-color: #00ff88;
            font-weight: 700;
            box-shadow: 0 0 20px rgba(0, 255, 136, 0.35);
        }
        .btn.primary:hover {
            background: #00ee77;
            box-shadow: 0 0 30px rgba(0, 255, 136, 0.5);
        }
        .btn.danger {
            border-color: #ff4466;
            color: #ff4466;
        }
        .btn.danger:hover {
            background: rgba(255, 68, 102, 0.1);
            box-shadow: 0 0 16px rgba(255, 68, 102, 0.25);
        }
        .difficulty-badge {
            font-size: 0.75rem;
            padding: 5px 12px;
            border-radius: 20px;
            background: rgba(255, 170, 68, 0.15);
            color: #ffaa44;
            border: 1px solid rgba(255, 170, 68, 0.3);
            font-weight: 500;
            cursor: pointer;
            transition: all 0.25s;
        }
        .difficulty-badge:hover {
            background: rgba(255, 170, 68, 0.25);
        }

        /* 移动端方向键 */
        .mobile-dpad {
            display: none;
            grid-template-areas:
                ". up ."
                "left . right"
                ". down .";
            grid-template-columns: repeat(3, 56px);
            grid-template-rows: repeat(3, 56px);
            gap: 6px;
        }
        .dpad-btn {
            width: 56px;
            height: 56px;
            border-radius: 14px;
            border: 1px solid var(--border);
            background: rgba(255, 255, 255, 0.04);
            color: #ccc;
            font-size: 1.4rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.15s;
            -webkit-tap-highlight-color: transparent;
        }
        .dpad-btn:active {
            background: rgba(0, 255, 136, 0.25);
            border-color: #00ff88;
            box-shadow: 0 0 12px rgba(0, 255, 136, 0.3);
            transform: scale(0.9);
        }
        .dpad-up {
            grid-area: up;
        }
        .dpad-down {
            grid-area: down;
        }
        .dpad-left {
            grid-area: left;
        }
        .dpad-right {
            grid-area: right;
        }

        @media (max-width: 520px) {
            .game-wrapper {
                padding: 14px 10px 12px;
                border-radius: 18px;
                gap: 10px;
            }
            .title {
                font-size: 1.3rem;
            }
            .score-value {
                font-size: 1.2rem;
            }
            .btn {
                padding: 8px 14px;
                font-size: 0.8rem;
            }
            .mobile-dpad {
                display: grid;
            }
            canvas {
                border-radius: 10px;
            }
            .overlay-text {
                font-size: 2rem;
            }
        }
        @media (min-width: 521px) {
            .mobile-dpad {
                display: none !important;
            }
        }
    </style>
</head>
<body>

    <!-- 背景粒子 -->
    <div class="bg-particles" id="bgParticles"></div>

    <div class="game-wrapper" id="gameWrapper">
        <!-- 头部 -->
        <div class="header">
            <div class="title-area">
                <span class="title-icon">🐍</span>
                <span class="title">贪吃蛇</span>
            </div>
            <div class="score-panel">
                <span class="score-label">得分</span>
                <span class="score-value" id="scoreDisplay">0</span>
                <span class="best-score">最高 <span id="bestScoreDisplay">0</span></span>
            </div>
            <span class="difficulty-badge" id="difficultyBadge" title="点击切换难度">⚡ 普通</span>
        </div>

        <!-- 画布区 -->
        <div class="canvas-container" id="canvasContainer">
            <canvas id="gameCanvas"></canvas>
            <div class="overlay" id="overlay">
                <div class="overlay-text" id="overlayText">游戏结束</div>
                <div class="overlay-sub" id="overlaySub"></div>
                <div class="overlay-hint">按空格键 或 点击按钮重新开始</div>
            </div>
        </div>

        <!-- 控制按钮 -->
        <div class="controls">
            <button class="btn primary" id="btnRestart">🔄 重新开始</button>
            <button class="btn" id="btnPause">⏯️ 暂停</button>
            <button class="btn danger" id="btnResetBest">🗑️ 清除记录</button>
        </div>

        <!-- 移动端方向键 -->
        <div class="mobile-dpad" id="mobileDpad">
            <button class="dpad-btn dpad-up" data-dir="up">▲</button>
            <button class="dpad-btn dpad-left" data-dir="left">◀</button>
            <button class="dpad-btn dpad-right" data-dir="right">▶</button>
            <button class="dpad-btn dpad-down" data-dir="down">▼</button>
        </div>
    </div>

    <script>
        (function() {
            // ==================== 背景粒子效果 ====================
            const bgContainer = document.getElementById('bgParticles');
            const particleColors = ['rgba(0,255,136,0.5)', 'rgba(0,220,200,0.4)', 'rgba(255,68,102,0.4)',
                'rgba(180,130,255,0.3)'
            ];
            for (let i = 0; i < 35; i++) {
                const p = document.createElement('div');
                p.classList.add('bg-particle');
                p.style.left = Math.random() * 100 + '%';
                p.style.width = (Math.random() * 4 + 2) + 'px';
                p.style.height = p.style.width;
                p.style.background = particleColors[Math.floor(Math.random() * particleColors.length)];
                p.style.animationDuration = (Math.random() * 12 + 8
